a:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-service-key',h,'sale.cashier','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-service-order","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-service-item","product_id":"lab-service-product","product_name":"Synthetic service","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-service-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-service-order","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
b:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-service-key',h,'sale.cashier','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-service-order","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-service-item","product_id":"lab-service-product","product_name":"Synthetic service","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-service-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-service-order","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
IF a IS DISTINCT FROM b OR (a->>'success')::boolean IS DISTINCT FROM true OR (SELECT count(*) FROM public.pos_sales WHERE id='lab-service-order')<>1 OR (SELECT count(*) FROM public.pos_sale_payments WHERE sale_id='lab-service-order')<>1 OR (SELECT count(*) FROM public.pos_cash_movements WHERE sale_id='lab-service-order')<>1 OR (SELECT count(*) FROM public.pos_inventory_movements WHERE product_id='lab-service-product')<>0 OR NOT (SELECT checkout_closed_at IS NOT NULL AND payment_status='paid' FROM public.pos_restaurant_orders WHERE id='lab-service-order-row') THEN RAISE EXCEPTION 'CASHIER_SERVICE_EFFECTS_MISMATCH'; END IF;
